def standalone_events(
    events: pd.DataFrame,
    *,
    universe_id: str,
    family_id: str,
) -> pd.DataFrame:
    frame = events.loc[
        (events["universe_id"] == universe_id) & (events["family_id"] == family_id)
    ].copy()
    frame["support_families"] = family_id
    return frame.sort_values(
        ["timestamp", "membership_rank", "pair"],
        kind="stable",
    ).reset_index(drop=True)

