def union_events(
    events: pd.DataFrame,
    *,
    universe_id: str,
    families: tuple[str, ...],
) -> pd.DataFrame:
    allowed = set(families)
    frame = events.loc[
        (events["universe_id"] == universe_id) & (events["family_id"].isin(allowed))
    ].copy()
    rows: list[dict[str, Any]] = []
    grouped = frame.groupby(["timestamp", "pair"], sort=True)
    for (timestamp, pair), group in grouped:
        family_set = tuple(sorted(set(group["family_id"].astype(str))))
        ranks = pd.to_numeric(group["membership_rank"], errors="raise").astype(int)
        periods = sorted(set(group["period_id"].astype(str)))
        if len(periods) != 1:
            raise RD24Error("union event spans multiple period labels")
        rows.append(
            {
                "timestamp": pd.Timestamp(timestamp),
                "pair": str(pair),
                "membership_rank": int(ranks.min()),
                "period_id": periods[0],
                "support_families": "|".join(family_set),
                "support_count": len(family_set),
            }
        )
    if not rows:
        return pd.DataFrame(
            columns=[
                "timestamp",
                "pair",
                "membership_rank",
                "period_id",
                "support_families",
                "support_count",
            ]
        )
    return (
        pd.DataFrame.from_records(rows)
        .sort_values(
            ["timestamp", "membership_rank", "pair"],
            kind="stable",
        )
        .reset_index(drop=True)
    )

def union_events(
    events: pd.DataFrame,
    *,
    universe_id: str,
) -> pd.DataFrame:
    frame = events.loc[events["universe_id"] == universe_id].copy()
    rows: list[dict[str, Any]] = []
    grouped = frame.groupby(["timestamp", "pair"], sort=True)
    for (timestamp, pair), group in grouped:
        family_set = tuple(sorted(set(group["family_id"].astype(str))))
        ranks = pd.to_numeric(group["membership_rank"], errors="raise").astype(int)
        periods = sorted(set(group["period_id"].astype(str)))
        atrs = pd.to_numeric(group["atr24_at_signal"], errors="raise").astype(float)
        if len(periods) != 1:
            raise RD26Error("union event spans multiple period labels")
        if float(atrs.max() - atrs.min()) > 1e-12:
            raise RD26Error("same pair-time union event has inconsistent ATR")
        rows.append(
            {
                "timestamp": pd.Timestamp(timestamp),
                "pair": str(pair),
                "membership_rank": int(ranks.min()),
                "period_id": periods[0],
                "support_families": "|".join(family_set),
                "support_count": len(family_set),
                "atr24_at_signal": float(atrs.iloc[0]),
            }
        )
    if not rows:
        return pd.DataFrame(
            columns=[
                "timestamp",
                "pair",
                "membership_rank",
                "period_id",
                "support_families",
                "support_count",
                "atr24_at_signal",
            ]
        )
    return (
        pd.DataFrame.from_records(rows)
        .sort_values(
            ["timestamp", "membership_rank", "pair"],
            kind="stable",
        )
        .reset_index(drop=True)
    )
